package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The sheet's periods, the earliest first. */
    List<Period> findBySheetIdOrderByFromAsc(String sheetId);

    /** Whether a period on the sheet has this name, ignoring case. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and lower(p.name) = lower(:name)")
    boolean nameInUse(@Param("sheetId") String sheetId, @Param("name") String name);

    /** The sheet's period by name. */
    Optional<Period> findBySheetIdAndName(String sheetId, String name);

    /** Whether a closed period on the sheet contains the date. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean closedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);
}
-- A sheet's period: a name unique on the sheet (compared without regard to case, kept trimmed) and
-- a from and to date, both inclusive, from on or before to. No two periods on a sheet overlap; a
-- claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A period can be closed. Closing fixes its due-total at that moment (two decimals): later changes
-- to rates do not alter it. No claim dated inside a closed period can be added, edited, opened,
-- settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
-- Closing a period fixes, besides its own due-total, each person's due-total for it at that moment:
-- one row for every person on the sheet then (two decimals). A person added later has no row and
-- counts 0.00 for the period. Reopening removes the rows: the figures are live again.
CREATE TABLE period_person_total (
    period_id BIGINT NOT NULL REFERENCES period (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    total DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);

