    /** Close, as a close by hand would, every open period whose to-date plus the sheet's grace days is
     *  before the sheet's today, in order of their to-dates, each recorded with auto=yes; nothing when
     *  the grace days are blank (off). The sheet's permission matrix governs a close by hand, not this
     *  one. Made when the sheet's today is changed, after it is set. */
    @Transactional
    public void autoClose(String sheetId, String user) {
        sheets.lock(sheetId);
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) {
            return;
        }
        LocalDate today = sheets.today(sheetId);
        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && p.getTo().plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::getTo))
                .forEach(p -> closeFixing(sheetId, user, p, " auto=yes"));
    }

    private Period closeFixing(String sheetId, String user, Period period, String suffix) {
        String name = period.getName();
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        LocalDate today = sheets.today(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        byId.keySet().forEach(id -> personTotals.put(id, BigDecimal.ZERO.setScale(2)));
        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null
                    || !claim.countsAsOf(atEnd.get(claim.getId()), holds.getOrDefault(person.getId(), List.of()), today)
                    || !period.contains(claim.getDate())) {
                continue;
            }
            BigDecimal due = claimService.dueOf(sheetId, person, claim);
            if (due != null) {
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        period.close(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
                + " total=" + total.toPlainString() + suffix);
        return saved;
    }

    /** Reopen a closed period, making its due-total live again. Only a role the sheet's
     *  permission matrix allows may (by the standing rule a steward); a period that is not closed is refused. */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        sheets.lock(sheetId);
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
        if (!settings.allows(sheetId, user, Permission.REOPEN)) {
            throw new PeriodRefusedException("Your role may not reopen the period " + name);
        }
        if (!period.isClosed()) {
            throw new PeriodRefusedException("The period " + name + " is not closed");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + name);
        return saved;
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.TreeMap;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /** A period as the screen shows it; closedPersonTotals is each person's due-total for it fixed
     *  when it was closed, by person id (empty while it is open). */
    public record PeriodView(Long id, String name, LocalDate from, LocalDate to, boolean closed,
            String closedTotal, Map<Long, String> closedPersonTotals) {
        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getPersonTotals().forEach((id, total) -> personTotals.put(id, total.toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(),
                    period.isClosed(),
                    period.getClosedTotal() != null ? period.getClosedTotal().toPlainString() : null,
                    personTotals);
        }
    }

    /** A period: a name and its from and to dates. */
    public record PeriodRequest(@NotBlank @Size(max = 200) String name,
            @NotNull LocalDate from, @NotNull LocalDate to) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    /** The sheet's periods, the earliest first. */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        return service.list(sheetId.trim()).stream().map(PeriodView::of).toList();
    }

    /** Add a period to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PeriodRequest request) {
        return PeriodView.of(service.add(sheetId.trim(), SignedInUser.decode(user), request.name().trim(),
                request.from(), request.to()));
    }

    /** Monthly periods to generate: the dates whose months they run from and to; a blank date is the
     *  sheet's today. */
    public record GenerateRequest(LocalDate from, LocalDate to) {
    }

    /** How many periods a generate made. */
    public record GenerateView(int made) {
    }

    /** Generate one period per calendar month between two dates, leaving out months taken. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody GenerateRequest request) {
        return new GenerateView(service.generate(sheetId.trim(), SignedInUser.decode(user), request.from(),
                request.to()));
    }

    /** Close a period, fixing its due-total. */
    @PostMapping("/{name}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable String name,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.close(sheetId.trim(), SignedInUser.decode(user), name));
    }

    /** Reopen a closed period, making its due-total live again; only a steward may. */
    @PostMapping("/{name}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable String name,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), SignedInUser.decode(user), name));
    }

    /** A period already closed is refused. */
    @ExceptionHandler(PeriodClosedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void closed() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** A name taken, dates running backwards, a period overlapping another, or a reopen by other
     *  than a steward or of a period not closed is refused. */
    @ExceptionHandler({PeriodRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** A date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The sheet's periods, the earliest first. */
    List<Period> findBySheetIdOrderByFromAsc(String sheetId);

    /** Whether a period on the sheet has this name, ignoring case. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and lower(p.name) = lower(:name)")
    boolean nameInUse(@Param("sheetId") String sheetId, @Param("name") String name);

    /** The sheet's period by name. */
    Optional<Period> findBySheetIdAndName(String sheetId, String name);

    /** Whether a closed period on the sheet contains the date. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean closedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);
}
-- A sheet's period: a name unique on the sheet (compared without regard to case, kept trimmed) and
-- a from and to date, both inclusive, from on or before to. No two periods on a sheet overlap; a
-- claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A period can be closed. Closing fixes its due-total at that moment (two decimals): later changes
-- to rates do not alter it. No claim dated inside a closed period can be added, edited, opened,
-- settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
-- Closing a period fixes, besides its own due-total, each person's due-total for it at that moment:
-- one row for every person on the sheet then (two decimals). A person added later has no row and
-- counts 0.00 for the period. Reopening removes the rows: the figures are live again.
CREATE TABLE period_person_total (
    period_id BIGINT NOT NULL REFERENCES period (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    total DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);

